using namespace pvz;using J=nlohmann::json;using Session=typed72app::Session;
namespace {
void need(bool condition,const std::string& why){if(!condition)throw std::runtime_error(why);}
J json(const V& v){return J::parse(dump(v));}
std::unique_ptr<Session> match(bool test=true,bool night=true,const char* mode="duel",bool flat=false){
 J scenario={{"fixture_flat",flat},{"seed",744},{"mode",mode},{"night",night},{"weather","clear"},{"durable_heroes",true},{"decks",{{"plant",J::array()},{"zombie",J::array()}}},{"rules",{{"deathmatch_seconds",100000.},{"local_test_mode",test}}}};
 if(std::string(mode)=="duo"){scenario["decks"]["plant2"]=J::array();scenario["decks"]["zombie2"]=J::array();}
 if(!test||std::string(mode)!="duel")for(auto& [side,deck]:scenario["decks"].items())deck=side.starts_with("plant")?J{"plant:豌豆射手"}:J{"zombie:普通僵尸","zombie:脑光墓碑"};
 auto h=battle_from_scenario(scenario);auto cold=typed72app::export_cold(h.battle,744.);cold.cold["battle"]["rules"]["local_test_mode"]=test;auto out=Session::create(std::move(cold),"testmode-audit");callm(h.battle,SY("close"),Args{});return out;
}
void command(Session& s,const std::string& side,J data){static int64_t seq=0;data["seq"]=++seq;data["type"]="test_mode";const auto error=s.command(side,data);need(error.empty(),error);}
J zombies(Session& s){return s.native_view().at("g").at("僵尸");}
J unit(Session& s,const std::string& id){for(const auto& row:zombies(s))if(row.value("_pvp_id",std::string{})==id)return row;return nullptr;}
int count(Session& s,int type){int n=0;for(const auto& u:zombies(s))if(u.contains("terraria")&&u["terraria"]["type"]==type)++n;return n;}
std::string spawn(Session& s,const std::string& name,double x=1800.,double y=650.){auto u=s.spawn("zombie:"+name,"zombie",x,y,1.,false);need(bool(u),"spawn failed: "+name);s.sync_public();return *u;}
void steps(Session& s,int n){for(int i=0;i<n;++i)s.step();}
}
